public abstract class AbstractSaveTraceTask : Task {
	protected Trace trace;
	protected AskTraceResult asked;
	protected bool force;
	protected PluginTool tool;

	protected CompletableFuture<Void> future = new();

	public AbstractSaveTraceTask(string title, PluginTool tool, Trace trace, AskTraceResult asked,
			bool force) : base(title, true, true, true)
    {
		this.tool = tool;
		this.trace = trace;
		this.asked = asked;
		this.force = force;
	}

	protected DomainObjectLockHold maybeLock(Trace trace, bool @lock) {
		if (!@lock) {
			return null;
		}
		return DomainObjectLockHold.forceLock(trace, false, getTaskTitle());
	}

	protected abstract void saveTrace(TaskMonitor monitor);

